28	namespace {
29	
30	int g_failures = 0;
31	int g_checks = 0;
32	int g_skipped = 0;
33	
34	void check(bool condition, std::string_view what) {
35	    ++g_checks;
36	    if (!condition) {
37	        ++g_failures;
38	        std::cerr << "FAIL: " << what << '\n';
39	    }
40	}
