42	namespace fs = std::filesystem;
43	
44	using branchaudit::Digest;
45	
46	std::string hex_of(const Digest& d) {
47	    return branchaudit::to_hex(d);
48	}
49	
50	Digest leaf_bytes(const std::vector<unsigned char>& data) {
51	    return branchaudit::merkle_leaf(data.data(), data.size());
52	}
53	
54	std::vector<unsigned char> bytes_of(std::string_view s) {
55	    return std::vector<unsigned char>(s.begin(), s.end());
56	}
57	
58	std::vector<unsigned char> fill_a(std::size_t n) {
59	    return std::vector<unsigned char>(n, static_cast<unsigned char>('a'));
60	}
61	
62	std::vector<unsigned char> pattern(std::size_t n) {
63	    std::vector<unsigned char> v(n);
64	    for (std::size_t i = 0; i < n; ++i) {
65	        v[i] = static_cast<unsigned char>((i * 31 + 7) % 256);
66	    }
67	    return v;
68	}
69	
70	struct TempArea {
71	    fs::path root;
72	    explicit TempArea(const std::string& tag) {
73	        const auto cwd_hash = std::hash<fs::path>{}(fs::current_path());
74	        root = fs::temp_directory_path() /
75	               ("branchaudit_merkle_test_" + tag + "_" +
76	                std::to_string(static_cast<std::uint64_t>(cwd_hash)));
77	        fs::remove_all(root);
78	        fs::create_directories(root);
79	    }
80	    ~TempArea() { std::error_code ec; fs::remove_all(root, ec); }
81	};
82	
83	void write_file(const fs::path& p, const std::vector<unsigned char>& bytes) {
84	    fs::create_directories(p.parent_path());
85	    std::ofstream out(p, std::ios::binary | std::ios::trunc);
86	    out.write(reinterpret_cast<const char*>(bytes.data()),
87	              static_cast<std::streamsize>(bytes.size()));
88	    check(static_cast<bool>(out), std::string("write fixture ") + p.string());
89	}
90	
91	Digest root_of(const std::vector<fs::path>& paths) {
92	    const branchaudit::FileHashResult r = branchaudit::merkle_root_files(paths);
93	    check(r.ok(), std::string("merkle_root_files succeeds: ") + r.error);
94	    return r.digest;
95	}
96	
97	// 调用库接口期间截获标准输出/错误：库只返回结果，不自行打印、不退出。
98	std::pair<std::string, std::string> silent_merkle(
99	        const std::vector<fs::path>& paths, branchaudit::FileHashResult* out) {
100	    std::stringstream cap_out, cap_err;
101	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
102	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
103	    *out = branchaudit::merkle_root_files(paths);
104	    std::cout.rdbuf(old_out);
105	    std::cerr.rdbuf(old_err);
106	    return {cap_out.str(), cap_err.str()};
107	}
