109	// ---- 空批次根 -------------------------------------------------------------
110	
111	void test_empty_batch() {
112	    const Digest empty_root = branchaudit::merkle_empty_root();
113	    check(hex_of(empty_root) ==
114	              "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
115	          "empty batch root is SHA-256 of empty byte sequence");
116	
117	    const branchaudit::FileHashResult r =
118	        branchaudit::merkle_root_files({});
119	    check(r.ok(), "zero files: succeeds");
120	    check(r.digest == empty_root, "zero files: root equals merkle_empty_root()");
121	
122	    // 空批次根必须与“单个空文件”的叶子摘要不同。
123	    const Digest leaf_empty = leaf_bytes({});
124	    check(hex_of(leaf_empty) ==
125	              "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
126	          "leaf of empty file is SHA-256(0x00)");
127	    check(leaf_empty != empty_root,
128	          "empty batch root differs from single empty-file leaf");
129	}
130	
131	// ---- 叶子：0x00 前缀与原始字节 --------------------------------------------
132	
133	void test_leaf_rule() {
134	    check(hex_of(leaf_bytes(bytes_of("a"))) ==
135	              "022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c",
136	          "leaf('a') = SHA-256(0x00 || 'a')");
137	    check(hex_of(leaf_bytes(bytes_of("abc"))) ==
138	              "609f6e36d2405585188d5cfd761f407c7cc46a7d3f314c88270469dde315fcd1",
139	          "leaf('abc') = SHA-256(0x00 || 'abc')");
140	    check(hex_of(leaf_bytes(bytes_of("hello\n"))) ==
141	              "54a6dc1bfc990ced3f5757264f357ad708a9ee54ce3d117299641b234f6d5800",
142	          "leaf('hello\\n') includes raw newline byte");
143	
144	    // 叶子不是普通 hash：0x00 前缀必须改变结果。
145	    branchaudit::Sha256 plain;
146	    const unsigned char a_byte = 'a';
147	    plain.update(&a_byte, 1);
148	    const Digest plain_a = plain.final();
149	    check(hex_of(plain_a) ==
150	              "ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb",
151	          "plain SHA-256('a') reference (no prefix)");
152	    check(leaf_bytes(bytes_of("a")) != plain_a,
153	          "leaf('a') must not equal plain hash('a')");
154	
155	    // 分组/填充边界长度的叶子（前缀使总长度 +1，覆盖各边界）。
156	    struct BCase { std::size_t n; const char* hex; };
157	    const BCase cases[] = {
158	        {55,  "2f96780fb415b287dd95897a04ef96fde6a5f5b0c771d0a1175543bc3250718e"},
159	        {56,  "4632d4b47c0932896996fe232ae65a5af500608fabd0bdbfbb6856795eaf9d85"},
160	        {63,  "5ec0fdb427bf003f71ceb018dfedc0028590a422eaf9f15a69dd1e5a6aa03d5e"},
161	        {64,  "88df0645999a1bc9dec19086e862403750a069436d7ecf7775256f78279b3fcb"},
162	        {65,  "3f104f71a21ddad6e23bac5b43967f5eed6675a5adf0c4050de374fff8055af7"},
163	        {128, "6023f14a3b7582c7e389f4ef3313bc3c6cbf69623e12a7d19485553d02d1f635"},
164	    };
165	    for (const BCase& c : cases) {
166	        check(hex_of(leaf_bytes(fill_a(c.n))) == c.hex,
167	              "leaf of 'a'*" + std::to_string(c.n) + " matches independent value");
168	    }
169	}
170	
171	// ---- 父节点：0x01 前缀、原始 32 字节、先左后右 -----------------------------
172	
173	void test_parent_rule() {
174	    const Digest la = leaf_bytes(bytes_of("a"));
175	    const Digest lbc = leaf_bytes(bytes_of("abc"));
176	
177	    check(hex_of(branchaudit::merkle_parent(la, lbc)) ==
178	              "6a5c0676c6dd1efd519348f49315879d99549029726d5dd1a5dedbf700720761",
179	          "parent(leaf('a'), leaf('abc')) = SHA-256(0x01||left||right)");
180	
181	    // 左右顺序不可交换。
182	    check(branchaudit::merkle_parent(la, lbc) != branchaudit::merkle_parent(lbc, la),
183	          "parent is ordered: parent(a,abc) != parent(abc,a)");
184	    check(hex_of(branchaudit::merkle_parent(lbc, la)) ==
185	              "ece02d1ac6ea17f528a19562aea6b77f7e7d1d8224a7583d3fbfc9f6e3d426ab",
186	          "parent(leaf('abc'), leaf('a')) independent value");
187	}
188	
189	// ---- 逐文件批次：顺序、重复、奇数提升、路径无关 ---------------------------
190	
191	void test_file_batches() {
192	    TempArea tmp("batches");
193	
194	    const auto empty = bytes_of("");
195	    const auto a = bytes_of("a");
196	    const auto abc = bytes_of("abc");
197	    const auto hello = bytes_of("hello\n");
198	
199	    const fs::path f_empty = tmp.root / "empty.bin";
200	    const fs::path f_a = tmp.root / "a.bin";
201	    const fs::path f_abc = tmp.root / "abc.bin";
202	    const fs::path f_hello = tmp.root / "hello.bin";
203	    write_file(f_empty, empty);
204	    write_file(f_a, a);
205	    write_file(f_abc, abc);
206	    write_file(f_hello, hello);
207	
208	    // 单文件批次：根即叶子摘要。
209	    check(hex_of(root_of({f_a})) == hex_of(leaf_bytes(a)),
210	          "single file: root equals its leaf digest");
211	    check(hex_of(root_of({f_a})) ==
212	              "022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c",
213	          "single file root('a') is leaf, not plain hash");
214	    check(hex_of(root_of({f_empty})) ==
215	              "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
216	          "single empty file root differs from empty batch root");
217	
218	    // 两文件、顺序敏感。
219	    check(hex_of(root_of({f_a, f_abc})) ==
220	              "6a5c0676c6dd1efd519348f49315879d99549029726d5dd1a5dedbf700720761",
221	          "root [a, abc]");
222	    check(hex_of(root_of({f_abc, f_a})) ==
223	              "ece02d1ac6ea17f528a19562aea6b77f7e7d1d8224a7583d3fbfc9f6e3d426ab",
224	          "root [abc, a] differs when order is reversed");
225	
226	    // 三文件：末节点原样提升。结构 = parent(parent(La,Lbc), Lempty)。
227	    const Digest p = branchaudit::merkle_parent(leaf_bytes(a), leaf_bytes(abc));
228	    const Digest three = branchaudit::merkle_parent(p, leaf_bytes(empty));
229	    check(hex_of(three) ==
230	              "b3beb69a3342155ac93f8fb124f5b39ec5955cdcbff261495547e03361f9c99a",
231	          "structural 3-file root with odd promotion (independent value)");
232	    check(root_of({f_a, f_abc, f_empty}) == three,
233	          "root [a, abc, empty] matches promoted (not duplicated) structure");
234	
235	    // 明确排除“复制末节点”与“补零”两种错误配对。
236	    const Digest dup_last = branchaudit::merkle_parent(
237	        p, branchaudit::merkle_parent(leaf_bytes(empty), leaf_bytes(empty)));
238	    check(dup_last != three,
239	          "odd node is never duplicated to make a pair");
240	    const Digest zeros{};
241	    check(branchaudit::merkle_parent(p, zeros) != three,
242	          "odd node is never zero-padded to make a pair");
243	
244	    // 不同位置的重复排列给出不同根（不按摘要重排、不去重）。
245	    check(hex_of(root_of({f_a, f_a, f_abc})) ==
246	              "d2b37c5ec897ce0504f95ec7a060d88c38664164a4614b5ca18e5dd3df527702",
247	          "root [a, a, abc] keeps both positions");
248	    check(hex_of(root_of({f_a, f_abc, f_a})) ==
249	              "588340eb2a7896e08c25b9af5be4538358eadeb56e0c685910ac0cc6fb12e006",
250	          "root [a, abc, a] differs from [a, a, abc]");
251	
252	    // 同一路径重复传入，保留两个位置。
253	    check(hex_of(root_of({f_a, f_a})) ==
254	              "8025de747bafe2560d6b991bdb17ca89efe1b6fedda1be209c0ee015338861ea",
255	          "same path twice keeps two positions");
256	    // 两个不同文件、内容相同，结果与重复同一路径一致。
257	    const fs::path f_a_copy = tmp.root / "copy of a.bin";
258	    write_file(f_a_copy, a);
259	    check(root_of({f_a, f_a_copy}) == root_of({f_a, f_a}),
260	          "identical content in distinct files behaves like repeated positions");
261	
262	    // 偶数四文件与奇数五文件（末节点先提升，再与其左侧在上层配对）。
263	    check(hex_of(root_of({f_a, f_abc, f_empty, f_hello})) ==
264	              "ae395b1592efa07192377a24fc187eba186da891a39c12d3dfae9df84f0c9a93",
265	          "root of 4 files");
266	    check(hex_of(root_of({f_a, f_abc, f_empty, f_hello, f_a})) ==
267	              "685686ca622026c4537dfdb49e8f9dac110c553f1d21aee96633e12fa47a7c47",
268	          "root of 5 files (odd promotion across levels)");
269	
270	    // 七文件树：跨层多次奇数提升。
271	    const std::array<std::vector<unsigned char>, 7> seven_data = {
272	        empty, a, bytes_of("bb"), bytes_of("ccc"), bytes_of("dddd"),
273	        bytes_of("eeeee"), bytes_of("ffffff")};
274	    std::array<fs::path, 7> seven;
275	    for (std::size_t i = 0; i < seven.size(); ++i) {
276	        seven[i] = tmp.root / ("seven" + std::to_string(i) + ".bin");
277	        write_file(seven[i], seven_data[i]);
278	    }
279	    check(hex_of(root_of({seven.begin(), seven.end()})) ==
280	              "80bea6847da15bd2a145bbce5c01fb61672c4ad0f91da2e282075758d2610de2",
281	          "root of 7 files (independent multi-level value)");
282	
283	    // 根只反映各位置内容：相同有序内容放在不同路径（含空格/中文目录），
284	    // 根相同。
285	    const fs::path alt_dir = tmp.root / "子 目录" / "另一批";
286	    std::array<fs::path, 3> alt;
287	    alt[0] = alt_dir / "空.bin";
288	    alt[1] = alt_dir / "a file.dat";
289	    alt[2] = tmp.root / "深 路径" / "文 件.bin";
290	    write_file(alt[0], empty);
291	    write_file(alt[1], a);
292	    write_file(alt[2], abc);
293	    const Digest r1 = root_of({f_empty, f_a, f_abc});
294	    const Digest r2 = root_of({alt[0], alt[1], alt[2]});
295	    check(r1 == r2, "root is path-independent: same ordered contents, other paths");
296	    // 顺序不同则根不同，确认不是按路径或摘要排序。
297	    check(root_of({alt[2], alt[1], alt[0]}) != r2,
298	          "different position order yields different root even with same files");
299	}
300	
301	// ---- 相对路径按当前工作目录解释 -------------------------------------------
302	
303	void test_relative_paths() {
304	    TempArea tmp("relative");
305	    write_file(tmp.root / "r1.bin", bytes_of("a"));
306	    write_file(tmp.root / "r2.bin", bytes_of("a"));
307	
308	    const fs::path prev = fs::current_path();
309	    fs::current_path(tmp.root);
310	    const branchaudit::FileHashResult r =
311	        branchaudit::merkle_root_files({"r1.bin", "r2.bin"});
312	    fs::current_path(prev);
313	
314	    check(r.ok(), "relative paths resolved from current working directory");
315	    check(hex_of(r.digest) ==
316	              "8025de747bafe2560d6b991bdb17ca89efe1b6fedda1be209c0ee015338861ea",
317	          "relative-path batch root matches independent value");
318	}
319	
320	// ---- 失败：缺失、目录、任一失败即整次失败 ---------------------------------
321	
322	void test_failures() {
323	    TempArea tmp("fail");
324	    const fs::path good1 = tmp.root / "good1.bin";
325	    const fs::path good2 = tmp.root / "good2.bin";
326	    write_file(good1, bytes_of("a"));
327	    write_file(good2, bytes_of("abc"));
328	
329	    const fs::path missing = tmp.root / "does not exist 缺失.bin";
330	    auto names_path = [&](const branchaudit::FileHashResult& r) {
331	        return r.error.find(missing.string()) != std::string::npos;
332	    };
333	
334	    branchaudit::FileHashResult r = branchaudit::merkle_root_files({missing});
335	    check(!r.ok(), "only missing file: batch fails");
336	    check(names_path(r), "missing file: error names the failed path");
337	    check(r.error.size() > missing.string().size() + 2,
338	          "missing file: error gives a reason beyond the path");
339	
340	    // 缺失位于中间：报错指出该路径，而非用其余文件算出结果。
341	    r = branchaudit::merkle_root_files({good1, missing, good2});
342	    check(!r.ok(), "missing file in middle: whole batch fails");
343	    check(names_path(r), "middle failure names the middle path");
344	
345	    // 缺失位于最前。
346	    r = branchaudit::merkle_root_files({missing, good1});
347	    check(!r.ok() && names_path(r), "missing file first: fails on that path");
348	
349	    // 目录不是文件。
350	    const fs::path dir = tmp.root / "a dir 目录";
351	    fs::create_directories(dir);
352	    r = branchaudit::merkle_root_files({good1, dir, good2});
353	    check(!r.ok(), "directory among files: batch fails");
354	    check(r.error.find(dir.string()) != std::string::npos,
355	          "directory: error names the failed path");
356	    check(r.error.find("directory") != std::string::npos,
357	          "directory: error states directory reason");
358	}
359	
360	// ---- 失败：文件存在却打不开 / 叶子读到一半出错 ----------------------------
361	//
362	// 与“缺失/目录”不同，这两类错误发生在文件真实存在、且读取已经（部分）
363	// 开始之后。经随测试预载的故障注入库在 libc 打开/读取接口确定性触发，
364	// 覆盖普通摘要与文件叶子共用的同一条文件计算路径。
365	
366	void test_io_failures() {
367	    TempArea tmp("iofail");
368	
369	    const fs::path good1 = tmp.root / "good1.bin";
370	    const fs::path good2 = tmp.root / "good2.bin";
371	    const fs::path bad = tmp.root / "present 出错.bin";
372	    const fs::path empty = tmp.root / "empty 空.bin";
373	    constexpr long kPartial = 40;
374	    const auto good_bytes1 = bytes_of("normal-file-one");
375	    const auto good_bytes2 = bytes_of("normal-file-two");
376	    const auto bad_bytes = pattern(200);
377	    write_file(good1, good_bytes1);
378	    write_file(good2, good_bytes2);
379	    write_file(bad, bad_bytes);
380	    write_file(empty, {});
381	
382	    const Digest good_leaf1 = leaf_bytes(good_bytes1);
383	    const Digest good_leaf2 = leaf_bytes(good_bytes2);
384	    const Digest bad_partial_leaf =
385	        branchaudit::merkle_leaf(bad_bytes.data(),
386	                                 static_cast<std::size_t>(kPartial));
387	
388	    // 夹具在无注入时必须成功，排除“写死错误结果”的可能。
389	    check(hex_of(root_of({good1, bad, good2})).size() == 64,
390	          "iofail fixtures: batch succeeds without injected fault");
391	
392	    // ---- 打开失败：唯一位置 --------------------------------------------
393	    {
394	        fault_test::FaultTrigger trigger(
395	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
396	        branchaudit::FileHashResult r;
397	        auto captured = silent_merkle({bad}, &r);
398	        check(!r.ok(), "unopenable leaf: batch fails");
399	        check(r.error.find(bad.string()) != std::string::npos,
400	              "unopenable leaf: error names the failed file");
401	        check(r.error.find("ermission") != std::string::npos ||
402	                  r.error.find("denied") != std::string::npos ||
403	                  r.error.find("cces") != std::string::npos,
404	              "unopenable leaf: error states open/permission reason");
405	        check(captured.first.empty() && captured.second.empty(),
406	              "unopenable leaf: library prints nothing, does not exit");
407	    }
408	
409	    // ---- 打开失败：有序批次中出错前已经处理过正常文件 ------------------
410	    {
411	        fault_test::FaultTrigger trigger(
412	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
413	        branchaudit::FileHashResult r;
414	        auto captured = silent_merkle({good1, good2, bad}, &r);
415	        check(!r.ok(),
416	              "open failure after processed good files: whole batch fails");
417	        check(r.error.find(bad.string()) != std::string::npos,
418	              "open failure in batch: error points at the real failing file");
419	        check(r.error.find(good1.string()) == std::string::npos &&
420	                  r.error.find(good2.string()) == std::string::npos,
421	              "open failure in batch: already-processed files are not blamed");
422	        check(captured.first.empty(),
423	              "open failure in batch: no root of the processed prefix is printed");
424	        check(captured.second.empty(),
425	              "open failure in batch: library prints nothing");
