506	// 用证明中的兄弟从叶子向根折叠，应回到证明给出的根。
507	Digest fold_proof(const branchaudit::MerkleProof& p) {
508	    Digest d = p.leaf;
509	    for (const branchaudit::MerkleSibling& s : p.siblings) {
510	        d = (s.side == branchaudit::MerkleSibling::Side::left)
511	                ? branchaudit::merkle_parent(s.digest, d)
512	                : branchaudit::merkle_parent(d, s.digest);
513	    }
514	    return d;
515	}
