696	// 直接调用校验：真实批次由 merkle_proof_file 产出，可信根由独立入口
697	// merkle_root_files 取得（绝不拿 proof.root 当信任锚喂回去）。
698	MerkleVerifyResult verify_real(const std::vector<fs::path>& batch,
699	                               std::uint64_t index, const Digest& content_leaf,
700	                               const Digest* trusted_override = nullptr) {
701	    const MerkleProofResult pr = branchaudit::merkle_proof_file(batch, index);
702	    check(pr.ok(), std::string("fixture proof succeeds: ") + pr.error);
703	    const Digest trusted = trusted_override
704	                               ? *trusted_override
705	                               : root_of(batch);
706	    return branchaudit::merkle_verify_proof(pr.proof, trusted, content_leaf);
707	}
