816	void test_verify_failures() {
817	    TempArea tmp("verify_bad");
818	    const auto a = bytes_of("a");
819	    const auto abc = bytes_of("abc");
820	    const auto empty = bytes_of("");
821	    const fs::path f_a = tmp.root / "a.bin";
822	    const fs::path f_abc = tmp.root / "abc.bin";
823	    const fs::path f_empty = tmp.root / "empty.bin";
824	    write_file(f_a, a);
825	    write_file(f_abc, abc);
826	    write_file(f_empty, empty);
827	
828	    const std::vector<fs::path> batch{f_a, f_abc, f_empty};
829	    const Digest trusted = root_of(batch);
830	    const Digest other_root = root_of({f_a, f_abc});
831	
832	    auto reject = [&](const MerkleProof& p, const Digest& root,
833	                      const Digest& leaf, std::string_view what) {
834	        const MerkleVerifyResult v =
835	            branchaudit::merkle_verify_proof(p, root, leaf);
836	        check(!v.ok() && !v.valid && !v.error.empty(), what);
837	    };
838	
839	    // 条件 1：内容叶子与证明叶子不符。
840	    {
841	        const MerkleProof p =
842	            branchaudit::merkle_proof_file(batch, 0).proof;
843	        reject(p, trusted, leaf_bytes(abc),
844	               "wrong content leaf (different file content) is rejected");
845	        // 普通文件摘要（无 0x00 前缀）不能替代叶子摘要。
846	        branchaudit::Sha256 plain;
847	        plain.update(reinterpret_cast<const unsigned char*>(a.data()),
848	                     a.size());
849	        reject(p, trusted, plain.final(),
850	               "plain hash digest without the 0x00 leaf prefix is rejected");
851	    }
