1037	    const Digest mar_leaf = leaf_bytes(mar);
1038	
1039	    const MerkleProofResult pr =
1040	        branchaudit::merkle_proof_file(batch, /*leaf_index=*/2);
1041	    check(pr.ok(), std::string("claimed-numbers fixture proof: ") + pr.error);
