1046	    check(proof.leaf_count == 3 && proof.leaf_index == 2,
1047	          "claimed-numbers fixture: proof self-reports count 3, index 2");
1048	    check(proof.leaf == mar_leaf,
1049	          "claimed-numbers fixture: proof leaf is the third file's 0x00 leaf");
1050	    check(proof.root == trusted,
1051	          "claimed-numbers fixture: generated root equals the independently "
1052	          "computed trusted root");
1053	    check(proof.siblings.size() == 1 &&
1054	                  proof.siblings[0].side == MerkleSibling::Side::left &&
1055	                  proof.siblings[0].digest ==
1056	                      branchaudit::merkle_parent(leaf_bytes(jan), leaf_bytes(feb)),
1057	          "claimed-numbers fixture: odd last node promoted without a sibling; "
1058	          "a single left sibling remains at the upper level");
