1060	    // 原证明在独立可信根与第三文件内容叶子下通过：valid 为真、error 为空。
1061	    {
1062	        const MerkleVerifyResult v =
1063	            branchaudit::merkle_verify_proof(proof, trusted, mar_leaf);
1064	        check(v.ok() && v.valid && v.error.empty(),
1065	              "original proof (count=3, index=2) verifies: valid is true and "
1066	              "error is empty");
1067	    }
