1071	    MerkleProof altered = proof;
1072	    altered.leaf_count = 2;
1073	    altered.leaf_index = 1;
1074	    check(altered.root == proof.root && altered.leaf == proof.leaf &&
1075	                  altered.siblings.size() == proof.siblings.size() &&
1076	                  altered.siblings[0].side == proof.siblings[0].side &&
1077	                  altered.siblings[0].digest == proof.siblings[0].digest,
