1083	    // 自洽。这种“声明数字改变、证明仍成立”的输入不能被误判为损坏。
1084	    {
1085	        const MerkleVerifyResult v =
1086	            branchaudit::merkle_verify_proof(altered, trusted, mar_leaf);
1087	        check(v.ok() && v.valid && v.error.empty(),
