1097	    };
1098	    check(claims_match_independent_fact(proof),
1099	          "the genuine proof's claims match the independently stored batch "
1100	          "fact (count 3, index 2)");
1101	    check(!claims_match_independent_fact(altered),
1102	          "the altered claims differ from the independent fact even though "
1103	          "verify passes: success is not a certification of count or position");
1104	
1105	    auto reject = [&](const MerkleProof& p, const Digest& root,
1106	                      const Digest& leaf, std::string_view what) {
1107	        const MerkleVerifyResult v =
1108	            branchaudit::merkle_verify_proof(p, root, leaf);
