1118	        wrong_pos.leaf_index = 0;
1119	        reject(wrong_pos, trusted, mar_leaf,
1120	               "altered proof with only the position changed to 0 is rejected: "
1121	               "a 2-leaf position 0 requires a right sibling, conflicting with "
1122	               "the retained left sibling");
1123	    }
1124	
1125	    // 拒绝边界 2：仍然自洽的改写证明换用不匹配的可信根也必须失败；声明
1126	    // 数字的等价性不能绕过可信根核对。
1127	    {
1128	        // 顺序不同的另一份批次（内容相同、排列改变）产生另一个根。
1129	        const Digest reordered_root = root_of({f_jan, f_mar, f_feb});
1130	        check(reordered_root != trusted,
1131	              "fixture: reordered batch yields a different root");
1132	        reject(altered, reordered_root, mar_leaf,
1133	               "altered proof fails against another batch's trusted root");
