1156	// ---- 64 位计数边界：纯结构推导，不按 leaf_count 分配内存 --------------------
1157	
1158	// 沿 (leaf_count, leaf_index) 计算生成端会记录的兄弟数与各层期望侧向，
1159	// 用独立的一份循环模拟证明形状（不调用生成接口，也不需要真实文件）。
1160	struct ShapeStep {
1161	    MerkleSibling::Side side;
1162	};
1163	std::vector<ShapeStep> expected_shape(std::uint64_t leaf_count,
1164	                                      std::uint64_t leaf_index) {
1165	    std::vector<ShapeStep> steps;
1166	    std::uint64_t n = leaf_count;
1167	    std::uint64_t pos = leaf_index;
1168	    while (n > 1) {
1169	        const bool promoted = (pos % 2 == 0) && (pos == n - 1);
1170	        if (!promoted) {
1171	            steps.push_back({(pos % 2 == 0) ? MerkleSibling::Side::right
1172	                                            : MerkleSibling::Side::left});
1173	        }
1174	        pos /= 2;
1175	        n -= n / 2;
1176	    }
1177	    return steps;
1178	}
