1180	void test_verify_uint64_limits() {
1181	    // 沿 (leaf_count, leaf_index) 按形状构造一份结构自洽的证明：兄弟摘要
1182	    // 全部取零，折叠结果与 root 字段、可信根保持一致，因此通过与否只取
1183	    // 决于结构推导是否无回绕、必定终止（不依赖真实文件或巨大内存）。
1184	    auto build_shaped_proof = [](std::uint64_t leaf_count,
1185	                                 std::uint64_t leaf_index,
1186	                                 const std::vector<ShapeStep>& shape) {
1187	        MerkleProof p;
1188	        p.leaf_count = leaf_count;
1189	        p.leaf_index = leaf_index;
1190	        Digest leaf{};
1191	        leaf[31] = 0x7f;
1192	        p.leaf = leaf;
1193	        Digest node = leaf;
1194	        for (const ShapeStep& st : shape) {
1195	            const Digest sib{};
1196	            if (st.side == MerkleSibling::Side::right) {
1197	                p.siblings.push_back({MerkleSibling::Side::right, sib});
1198	                node = branchaudit::merkle_parent(node, sib);
1199	            } else {
1200	                p.siblings.push_back({MerkleSibling::Side::left, sib});
1201	                node = branchaudit::merkle_parent(sib, node);
1202	            }
1203	        }
1204	        p.root = node;
1205	        return std::pair<MerkleProof, Digest>{p, node};
1206	    };
1207	
1208	    // leaf_count = UINT64_MAX（最大可表示的合法计数，奇数），位置 0：
1209	    // 位置 0 每层都是偶数下标且永不等于本层末下标，因此每层都有 right
1210	    // 兄弟。层数恰为 64：反复 ceil(n/2) 把 2^64-1 经 63 次提升变为 2，
1211	    // 第 64 层变为 1。结构循环必须走完 64 层、消费 64 项后终止。
1212	    constexpr std::uint64_t kMax = ~std::uint64_t{0};
1213	    {
1214	        const std::vector<ShapeStep> shape = expected_shape(kMax, 0);
1215	        check(shape.size() == 64,
1216	              "UINT64_MAX leaves index 0: exactly 64 right-sibling levels");
1217	        for (const ShapeStep& st : shape) {
1218	            check(st.side == MerkleSibling::Side::right,
1219	                  "UINT64_MAX leaves index 0: every sibling is on the right");
1220	        }
1221	
1222	        const auto [p, folded] = build_shaped_proof(kMax, 0, shape);
1223	        check(branchaudit::merkle_verify_proof(p, folded, p.leaf).ok(),
1224	              "UINT64_MAX leaves: structurally exact proof verifies "
1225	              "deterministically without wraparound");
1226	
1227	        // 可信根差一位：必须在完整走完 64 层结构核对后才失败于根比对。
1228	        Digest other = folded;
1229	        other[0] ^= 0x80;
1230	        check(!branchaudit::merkle_verify_proof(p, other, p.leaf).ok(),
1231	              "UINT64_MAX leaves: wrong trusted root rejected after the full "
1232	              "64-level traversal");
1233	
1234	        // 少最后一个兄弟：第 64 层缺项必须被发现，不能误判通过。
1235	        MerkleProof short_proof = p;
1236	        short_proof.siblings.pop_back();
1237	        check(!branchaudit::merkle_verify_proof(short_proof, folded, p.leaf).ok(),
1238	              "UINT64_MAX leaves: a missing sibling at the final level is "
1239	              "detected");
1240	
1241	        // 多一个兄弟：按形状只该有 64 项。
1242	        MerkleProof long_proof = p;
1243	        long_proof.siblings.push_back({MerkleSibling::Side::left, Digest{}});
1244	        check(!branchaudit::merkle_verify_proof(long_proof, folded, p.leaf).ok(),
1245	              "UINT64_MAX leaves: a trailing extra sibling is rejected");
1246	    }
1247	
1248	    // 位置取最大合法值 UINT64_MAX-1（偶数，恰为奇数层的末下标）：第 0 层
1249	    // 原样提升、不产生兄弟记录；之后每层节点数均为偶数、该位置都是奇数
1250	    // 下标，故共 63 条 left 兄弟。重点验证：首层省略提升记录不会被误判为
1251	    // 缺项，且奇数下标分支在极限值上不回绕。
1252	    {
1253	        const std::uint64_t last = kMax - 1;
1254	        const std::vector<ShapeStep> shape = expected_shape(kMax, last);
1255	        check(shape.size() == 63,
1256	              "UINT64_MAX leaves index UINT64_MAX-1: 63 records (level 0 "
1257	              "promoted without a sibling)");
1258	        for (const ShapeStep& st : shape) {
1259	            check(st.side == MerkleSibling::Side::left,
1260	                  "UINT64_MAX leaves index UINT64_MAX-1: every recorded "
1261	                  "sibling is on the left");
1262	        }
1263	
1264	        const auto [p, folded] = build_shaped_proof(kMax, last, shape);
1265	        check(branchaudit::merkle_verify_proof(p, folded, p.leaf).ok(),
1266	              "UINT64_MAX leaves at the last even position verifies without "
1267	              "integer wraparound and without a padded promotion record");
1268	    }
1269	
1270	    // leaf_index == leaf_count 是越界（即使两者都是最大可表示值）。
1271	    {
1272	        MerkleProof p;
1273	        p.leaf_count = kMax;
1274	        p.leaf_index = kMax;
1275	        p.leaf = Digest{};
1276	        check(!branchaudit::merkle_verify_proof(p, Digest{}, Digest{}).ok(),
1277	              "UINT64_MAX: leaf_index equal to leaf_count is out of range");
1278	    }
1279	
1280	    // 2 的幂边界 leaf_count = 2^63，末位置 2^63-1（奇数）：每层都有 left
1281	    // 兄弟、没有任何提升省略，共 63 条；这是“全左、无省略”的极限形状，
1282	    // 与前一块“首层省略”互为对照，两条路径上的下标推导都不得回绕。
1283	    {
1284	        constexpr std::uint64_t kPow2 = UINT64_C(1) << 63;
1285	        const std::uint64_t last = kPow2 - 1;
1286	        const std::vector<ShapeStep> shape = expected_shape(kPow2, last);
1287	        check(shape.size() == 63,
1288	              "2^63 leaves at the last position: 63 levels, none omitted");
1289	        for (const ShapeStep& st : shape) {
1290	            check(st.side == MerkleSibling::Side::left,
1291	                  "2^63 leaves last position: every sibling is on the left");
1292	        }
1293	        const auto [p, folded] = build_shaped_proof(kPow2, last, shape);
1294	        check(branchaudit::merkle_verify_proof(p, folded, p.leaf).ok(),
1295	              "2^63 leaves: structurally exact proof verifies deterministically");
1296	    }
1297	}
