1299	// ---- prove JSON 的读取：版本 1 格式严格校验、读入后接校验 -----------------
1300	
1301	using branchaudit::MerkleProofParseResult;
1302	
1303	// 把摘要数组拼成 prove 版本 1 的 JSON 文本；可用 write_json 做小范围改写。
1304	std::string proof_json(const Digest& root, std::uint64_t leaf_count,
1305	                       std::uint64_t leaf_index, const Digest& leaf,
1306	                       const std::vector<std::pair<MerkleSibling::Side, Digest>>&
1307	                           siblings) {
1308	    std::string s = "{\"version\":1,\"root\":\"" + hex_of(root) +
1309	                    "\",\"leaf_count\":" + std::to_string(leaf_count) +
1310	                    ",\"leaf_index\":" + std::to_string(leaf_index) +
1311	                    ",\"leaf\":\"" + hex_of(leaf) + "\",\"siblings\":[";
1312	    for (std::size_t i = 0; i < siblings.size(); ++i) {
1313	        if (i != 0) {
1314	            s += ',';
1315	        }
1316	        s += "{\"side\":\"";
1317	        s += siblings[i].first == MerkleSibling::Side::left ? "left" : "right";
1318	        s += "\",\"digest\":\"" + hex_of(siblings[i].second) + "\"}";
1319	    }
1320	    s += "]}";
1321	    return s;
1322	}
1323	
1324	// 读取成功路径并返回结果；what 描述该用例。
1325	MerkleProofParseResult expect_parse_ok(const std::string& text,
1326	                                       std::string_view what) {
1327	    // 截获输出：库读取不得打印。
1328	    std::stringstream cap_out, cap_err;
1329	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
1330	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
1331	    MerkleProofParseResult r = branchaudit::merkle_proof_from_json(text);
1332	    std::cout.rdbuf(old_out);
1333	    std::cerr.rdbuf(old_err);
1334	    check(r.ok(), std::string("parse ok: ") + std::string(what) +
1335	                      " — " + r.error);
1336	    check(cap_out.str().empty() && cap_err.str().empty(),
1337	          std::string("parse prints nothing: ") + std::string(what));
1338	    return r;
1339	}
1340	
1341	// 读取失败路径：必须失败、给出非空可展示原因且不打印。
1342	void expect_parse_fail(const std::string& text, std::string_view what) {
1343	    std::stringstream cap_out, cap_err;
1344	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
1345	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
1346	    MerkleProofParseResult r = branchaudit::merkle_proof_from_json(text);
1347	    std::cout.rdbuf(old_out);
1348	    std::cerr.rdbuf(old_err);
1349	    check(!r.ok(), std::string("parse rejected: ") + std::string(what));
1350	    check(!r.error.empty(),
1351	          std::string("parse failure gives a displayable reason: ") +
1352	              std::string(what));
1353	    check(cap_out.str().empty() && cap_err.str().empty(),
1354	          std::string("parse failure prints nothing: ") + std::string(what));
1355	    // 失败不提供可用的部分证明：结构保持默认构造（零计数、空兄弟）。
1356	    check(r.proof.leaf_count == 0 && r.proof.leaf_index == 0 &&
1357	              r.proof.siblings.empty(),
1358	          std::string("parse failure yields no usable partial proof: ") +
1359	              std::string(what));
1360	}
