1847	// 把 ASCII 字符 c 写成 JSON \u00XX 转义形式（小写十六进制）。
1848	std::string json_unicode_escape(char c) {
1849	    const char* hex = "0123456789abcdef";
1850	    const unsigned char u = static_cast<unsigned char>(c);
1851	    std::string e = "\\u00";
1852	    e += hex[u >> 4];
1853	    e += hex[u & 0xF];
1854	    return e;
1855	}
1856	
1857	// 字段名第 i 个字符改用 \u00XX 转义，其余字符保持普通写法（两种写法混用）。
1858	std::string escape_name_char(const std::string& name, std::size_t i) {
1859	    return name.substr(0, i) + json_unicode_escape(name[i]) +
1860	           name.substr(i + 1);
1861	}
1862	
1863	// 十六进制文本中的字母全部改写成 \u00XX 转义，数字保持原样：解码后与原
1864	// 字符串完全相同，但字面写法与长度都不同。
1865	std::string escape_hex_letters(const std::string& hex_text) {
1866	    std::string out;
1867	    for (char c : hex_text) {
1868	        if (c >= 'a' && c <= 'f') {
1869	            out += json_unicode_escape(c);
1870	        } else {
1871	            out += c;
1872	        }
1873	    }
1874	    return out;
1875	}
